import sys;sys.path.insert(0,'.')
from common7 import *
SN=E('English','እንግሊዝኛ')
def eq(en,am,opts,a=0,say=None):
    d={'q':E(en,am) if am else en,'o':[o if isinstance(o,str) else E(*o) for o in opts],'a':a}
    if say: d['say']=say;d['sayLang']='en-US'
    return d
def sq(sent,opts,a=0): return {'say':sent.replace('___',opts[a]),'sayLang':'en-US','q':sent,'o':opts,'a':a}
def read(ptitle,paras,items): return {'title':E('Read and answer','አንብቡና መልሱ'),'type':'quiz','tip':E('Listen to the passage, read it yourself, then answer.','ጽሑፉን አዳምጡ፣ ራሳችሁ አንብቡ፣ ከዚያ መልሱ።'),'passage':{'title':ptitle,'paras':paras,'say':' '.join(paras),'sayLang':'en-US'},'items':items}
def gq(title,tip,items): return quiz(title,tip,items)
def wm(pairs): return match(('Word meanings','የቃላት ፍቺ'),('Match each word from the unit with its meaning.','ከክፍሉ የተወሰዱ ቃላትን ከፍቺያቸው ጋር አዛምዱ።'),[[(a,b) for a,b in pairs]],say=False)
def U(n,title,data,extra,exam,nt,summ):
    unit(f'g7-english-{n}','english',SN,E(f'Unit {n}',f'ክፍል {n}'),E(*title),E(f'Built on English for Ethiopia, Grade 7, Unit {n}: {title[0]}.',f'በEnglish for Ethiopia 7ኛ ክፍል፣ ክፍል {n} ({title[1]}) ላይ የተመሰረተ።'),'K1.engMissions',data,extra,exam,nt,summ)
def sp(w,b,e,am): return {'w':w,'blanks':b,'e':e,'am':am}

